import React, { useEffect } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { RootState, AppDispatch } from '../../store/store';
import { fetchRecommendations } from '../../store/slices/recommendationsSlice';
import './Recommendations.css';

const Recommendations: React.FC = () => {
  const dispatch = useDispatch<AppDispatch>();
  const { recommendations, isLoading, error } = useSelector((state: RootState) => state.recommendations);

  useEffect(() => {
    dispatch(fetchRecommendations());
  }, [dispatch]);

  const getActionClass = (action: string | undefined) => {
    if (!action) return '';
    return action === 'TRADE' ? 'action-trade' : 'action-avoid';
  };

  const getConfidenceClass = (confidence: number | undefined) => {
    if (!confidence) return '';
    if (confidence >= 0.8) return 'confidence-high';
    if (confidence >= 0.6) return 'confidence-medium';
    return 'confidence-low';
  };

  if (isLoading) {
    return (
      <div className="recommendations">
        <div className="loading">Loading recommendations...</div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="recommendations">
        <div className="error">Error loading recommendations: {error}</div>
      </div>
    );
  }

  return (
    <div className="recommendations">
      <h1>Trading Recommendations</h1>
      
      <div className="recommendations-header">
        <div className="current-time">
          <h3>Current Time Analysis</h3>
          <div className="time-info">
            <span>Hour: {new Date().getHours()}:00</span>
            <span>Day: {new Date().toLocaleDateString('en-US', { weekday: 'long' })}</span>
          </div>
        </div>
        
        <div className="refresh-section">
          <button 
            className="refresh-btn"
            onClick={() => dispatch(fetchRecommendations())}
            disabled={isLoading}
          >
            Refresh Recommendations
          </button>
        </div>
      </div>

      <div className="recommendations-grid">
        {recommendations?.length ? (
          recommendations.map((rec, index) => {
            // Handle both new and old property names with proper undefined handling
            const accountName = rec.account_name || rec.accountName || 'Unknown';
            const recommendedAction = rec.recommended_action || rec.recommendedAction;
            const confidenceScore = rec.confidence_score ?? rec.confidenceScore;
            const expectedReturn = rec.expected_return ?? rec.expectedReturn;
            const expectedRisk = rec.expected_risk ?? rec.expectedRisk;
            const historicalWinRate = rec.historical_win_rate ?? rec.historicalWinRate;
            const avgProfitThisTime = rec.avg_profit_this_time ?? rec.avgProfitThisTime;
            
            return (
              <div key={rec.id || index} className="recommendation-card">
                <div className="recommendation-header">
                  <div className="account-symbol">
                    <h3>{accountName}</h3>
                    <span className="symbol">{rec.symbol}</span>
                  </div>
                  <div className={`action-badge ${recommendedAction ? getActionClass(recommendedAction) : ''}`}>
                    {recommendedAction || 'N/A'}
                  </div>
                </div>

                <div className="recommendation-metrics">
                  <div className="metric">
                    <span className="metric-label">Confidence</span>
                    <span className={`metric-value ${confidenceScore ? getConfidenceClass(confidenceScore) : ''}`}>
                      {confidenceScore ? (confidenceScore * 100).toFixed(1) : 'N/A'}%
                    </span>
                  </div>
                  <div className="metric">
                    <span className="metric-label">Expected Return</span>
                    <span className={`metric-value ${expectedReturn && expectedReturn >= 0 ? 'positive' : 'negative'}`}>
                      ${expectedReturn?.toFixed(2) || 'N/A'}
                    </span>
                  </div>
                  <div className="metric">
                    <span className="metric-label">Expected Risk</span>
                    <span className="metric-value">
                      {expectedRisk?.toFixed(2) || 'N/A'}%
                    </span>
                  </div>
                </div>

                <div className="historical-data">
                  <div className="historical-metric">
                    <span>Historical Win Rate:</span>
                    <span>{historicalWinRate ? (historicalWinRate * 100).toFixed(1) : 'N/A'}%</span>
                  </div>
                  <div className="historical-metric">
                    <span>Avg Profit (This Time):</span>
                    <span className={avgProfitThisTime && avgProfitThisTime >= 0 ? 'positive' : 'negative'}>
                      ${avgProfitThisTime?.toFixed(2) || 'N/A'}
                    </span>
                  </div>
                </div>

                <div className="reasoning">
                  <h4>Analysis</h4>
                  <p>{rec.reasoning || 'No detailed analysis available'}</p>
                </div>

                <div className="recommendation-footer">
                  <span className="timestamp">
                    Updated: {new Date(rec.timestamp).toLocaleString()}
                  </span>
                </div>
              </div>
            );
          })
        ) : (
          <div className="no-recommendations">
            <h3>No Recommendations Available</h3>
            <p>No trading recommendations are currently available. This could be due to:</p>
            <ul>
              <li>Insufficient historical data</li>
              <li>Market conditions not favorable</li>
              <li>All accounts showing high risk patterns</li>
            </ul>
          </div>
        )}
      </div>
    </div>
  );
};

export default Recommendations;
